/**
 * Ways to get help as cards or rows, each with an icon, a title, a sentence and an open link. Axes: layout
 * (grid, list), columns, action (link, none), tone (default, muted).
 */
import { type ReactNode } from "react";
import { Card } from "../primitives/card/card";
import { CardContent } from "../primitives/card/card-content";
import { Grid } from "../primitives/grid/grid";
import { Link } from "../primitives/link/link";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { SectionFrame } from "../components/section-frame";
import { cn } from "../utils";
import type { Feature } from "./feature-grid.types";

export type SupportChannelsProps = {
  id: string;
  title: string;
  channels: Feature[];
  open: string;
  layout?: "grid" | "list";
  cols?: "1-2" | "1-3";
  action?: "link" | "none";
  tone?: "default" | "muted";
};

export function SupportChannels({
  id,
  title,
  channels,
  open,
  layout = "grid",
  cols = "1-3",
  action = "link",
  tone = "default",
}: SupportChannelsProps) {
  return (
    <SectionFrame id={id} title={title} tone={tone}>
      <Grid cols={(((layout as string) === "list") ? "1" : cols)} className="gap-4" data-testid="items">
        {(channels ?? []).map((c) => (
          <Card key={c.id}
            variant="default"
            className={cn("h-full", (((layout as string) === "list") ? "flex-row items-center" : ""))}
            data-testid="item"
          >
            <CardContent className={cn("flex flex-1 gap-4", (((layout as string) === "list") ? "items-center" : "flex-col"))}>
              <LucideIcon name={c.icon} size={24} />
              <Stack gap="2" className="flex-1">
                <Title as={3} size="base" weight="bold">
                  {c.title}
                </Title>
                <Text size="sm" className="text-muted-foreground">
                  {c.text}
                </Text>
              </Stack>
              {((action as string) === "link") ? (
                <Link href="#/" variant="default" data-testid="open">
                  {open}
                </Link>
              ) : null}
            </CardContent>
          </Card>
        ))}
      </Grid>
    </SectionFrame>
  );
}
